-- Importação idempotente do quadro funcional oficial fornecido em servidores.json.
-- Fonte: 2.673 registros (matrícula, nome, cargo efetivo e lotação).
-- Departamento, setor, CPF e ramal não constam no arquivo de origem e permanecem nulos.

ALTER TABLE public.servidores
  ALTER COLUMN cpf DROP NOT NULL,
  ALTER COLUMN departamento_id DROP NOT NULL;

WITH dados AS (
  SELECT
    ordem,
    NULLIF(trim(item ->> 'Matrícula'), '') AS matricula,
    NULLIF(trim(item ->> 'Nome'), '') AS nome,
    COALESCE(NULLIF(trim(item ->> 'Cargo efetivo'), ''), 'Não informado') AS cargo,
    NULLIF(trim(item ->> 'Lotação'), '') AS lotacao
  FROM jsonb_array_elements(
    $dados$[
