INSERT INTO public.servidores (
  matricula, nome, cpf, cargo, lotacao, departamento_id, setor_id, ramal, status
)
SELECT DISTINCT ON (matricula)
  matricula,
  nome,
  NULL,
  cargo,
  lotacao,
  NULL,
  NULL,
  NULL,
  'ativo'::public.servidor_status
FROM dados
WHERE matricula IS NOT NULL AND nome IS NOT NULL
ORDER BY matricula, ordem DESC
ON CONFLICT (matricula) DO UPDATE SET
  nome = EXCLUDED.nome,
  cargo = EXCLUDED.cargo,
  lotacao = EXCLUDED.lotacao,
  status = 'ativo',
  updated_at = now();

-- Remova somente os registros fictícios que não possuem histórico vinculado.
-- Registros com histórico são preservados para manter a integridade da auditoria.
DELETE FROM public.servidores AS servidor
WHERE servidor.matricula IN (
  'SME-100201', 'SME-100452', 'SME-200781', 'SME-200994',
  'SME-300112', 'SME-400553', 'SME-500881'
)
AND NOT EXISTS (
  SELECT 1 FROM public.autorizacoes AS autorizacao
  WHERE autorizacao.servidor_solicitado_id = servidor.id
)
AND NOT EXISTS (
  SELECT 1 FROM public.agendamentos AS agendamento
  WHERE agendamento.servidor_visitante_id = servidor.id
);
